shell_commands:
node -e "
const l = require('./package-lock.json');
l.version = '0.4.0';
l.packages[''].version = '0.4.0';
require('fs').writeFileSync('./package-lock.json', JSON.stringify(l, null, 2) + '\n');
console.log('lock version ->', l.version);
" && git diff --stat package-lock.json

node --input-type=module -e "
import Ajv from 'ajv';
const ajv = new Ajv({strict: false, validateFormats: false});
const v = ajv.compile({type: 'object', properties: {ssn: {type: 'string'}}, required: ['ssn']});
console.log('missing:', ajv.errorsText(v.errors ?? []));
console.log('valid:', v({ssn: 'x'}));
console.log('wrongtype:', (v({ssn: 1}), ajv.errorsText(v.errors ?? [])));
"
